mapper.select:
SELECT LMS_PRF_ID
FROM LMS_PROFILE
WHERE MEMBER_ID = #{memberId}

mapper.update:
UPDATE LMS_PROFILE
SET LMS_PRF_EMAIL = #{dto.lmsProfessorProfileEmail},
    LMS_PRF_INTRO = #{dto.lmsProfessorProfileIntroduction}
WHERE MEMBER_ID = #{memberId}

mapper.insert:
INSERT INTO LMS_USER_SECESSION_REQUEST (
    LMS_USR_SEC_REQ_ID, LMS_PRF_ID, LMS_USR_SEC_REQ_REG_DATE, LMS_USR_SEC_REQ_STATUS
) VALUES (
    SEQ_LMS_USER_SECESSION_REQUEST.NEXTVAL, #{lmsPrfId}, SYSTIMESTAMP, #{status}
)
